const b=$json.body||{};
const required=['slotId','nom','prenom'];
for (const k of required) if (!b[k]) throw new Error(`Champ requis: ${k}`);
const clean=(v,max=255)=>String(v||'').trim().slice(0,max);
if (!/^[0-9a-fA-F-]{36}$/.test(String(b.slotId))) throw new Error('slotId invalide');
return [{json:{slotId:String(b.slotId),nom:clean(b.nom,100),prenom:clean(b.prenom,100),email:clean(b.email,255),telephone:clean(b.telephone,50),numeroDocument:clean(b.numeroDocument,100),langue:clean(b.langue||'fr',10)}}];
